FIXTURE_BYTES = zlib.decompress(base64.b64decode(FIXTURE_B64))
FIXTURES = [json.loads(line) for line in FIXTURE_BYTES.splitlines()]
SCHEMAS = {k: v.encode() for k, v in json.loads(zlib.decompress(base64.b64decode(SCHEMAS_B64))).items()}


class PathPlanTests(unittest.TestCase):
    def setUp(self):
        self.calls = []
        def fixture_validator(bundle, name, value):
            self.assertEqual(set(bundle), set(SCHEMAS))
            self.calls.append((name, value))
        self.config = PathAdmissionConfig(16 * 1024 * 1024, PathSchemaValidation(SCHEMAS, fixture_validator))

    def fixture(self, name):
        return copy.deepcopy(next(x for x in FIXTURES if x['test'] == name and x['response'].get('status') == 'compiled'))

    def admit(self, fixture):
        return admit_path_artifact(fixture['request'], fixture['response'], copy.deepcopy(fixture['response']), config=self.config)

    def obligation(self, artifact, name):
        return next(o for o in artifact['obligations'] if o['id'] == name)

    def test_actual_plain_counts_retain_owning_arithmetic_capacity(self):
        # Retained independent compiler controls, no compiler execution here.
        controls = json.loads(zlib.decompress(base64.b64decode('')))
        self.assertGreaterEqual(len(controls), 4)
        for fixture in controls:
            self.admit(fixture)
            mutated = copy.deepcopy(fixture)
            mutated['response']['obligations'].remove(self.obligation(mutated['response'], 'ashlar.arithmetic.exact'))
            with self.assertRaises(PathPlanError): self.admit(mutated)

    def test_all_complete_actual_compiled_profiles_and_frozen_inventory(self):
        self.assertEqual(hashlib.sha256(FIXTURE_BYTES).hexdigest(), '376c29438acc7fc9fd150716f2ff5845b391a1818ae2c029d803a1f134f61ca9')
        total = 0
        for original in FIXTURES:
            if original['response'].get('status') != 'compiled': continue
            fixture = copy.deepcopy(original)
            result = self.admit(fixture)
            self.assertEqual(len(result.columns), len(fixture['response']['columns']))
            self.assertEqual([o['id'] for o in result.obligations], [o['id'] for o in fixture['response']['obligations']])
            self.assertEqual(len(result.parameters), len(fixture['response']['parameters']))
            with self.assertRaises(TypeError): result.binding['profile'] = 'changed'
            fixture['response']['sql'] = 'changed after admission'
            self.assertNotEqual(result.artifact['sql'], fixture['response']['sql'])
            total += 1
        self.assertEqual(total, 17)
        self.assertEqual(len(self.calls), 34)

    def test_binding_source_profile_and_recompile_fences(self):
        name = 'original_collection_retains_pins_keys_wide_order_and_closed_inventory'
        for mutation in ['hash', 'source', 'old-interface', 'old-backend', 'unknown-obligation', 'pin']:
            x = self.fixture(name); r = x['response']
            if mutation == 'hash': x['request']['target']['bindingSha256'] = '0' * 64
            if mutation == 'source': x['request']['modules'][0]['documentJson'] += ' '
            if mutation == 'old-interface': r['interfaceVersion'] = 'weft-compile/0.3.0'
            if mutation == 'old-backend': r['backend']['interfaceVersion'] = 'weft-backend/0.2.0'
            if mutation == 'unknown-obligation': r['obligations'].append(dict(id='unknown', owner='host', failureCode='WFT-BINDING', parameters={}))
            if mutation == 'pin': r['modelPins'][0]['revision'] = 'wrong'
            with self.subTest(mutation=mutation), self.assertRaises(PathPlanError): self.admit(x)
        x = self.fixture(name)
        original = copy.deepcopy(x['response']); x['response']['sql'] += ' '
        with self.assertRaises(PathPlanError):
            admit_path_artifact(x['request'], x['response'], original, config=self.config)

    def test_per_hop_native_schema_and_path_guard_inventory(self):
        name = 'original_collection_retains_pins_keys_wide_order_and_closed_inventory'
        for mutation in ['missing-hop', 'hop-order', 'wrong-uuid', 'wrong-type', 'wrong-relation', 'missing-check', 'duplicate-check', 'wrong-bound', 'extra-param']:
            x = self.fixture(name)
            p = self.obligation(x['response'], 'ashlar.path.occurrenceIntegrity')['parameters']
            if mutation == 'missing-hop': p['edgeSchemas'].pop()
            if mutation == 'hop-order': p['edgeSchemas'].reverse()
            if mutation == 'wrong-uuid': p['edgeSchemas'][0]['table']['uuid'] = 'wrong'
            if mutation == 'wrong-type': p['edgeSchemas'][0]['nativeType'] = 'STRING'
            if mutation == 'wrong-relation': p['edgeSchemas'][0]['relationship']['relationship'] = 'wrong'
            if mutation == 'missing-check': p['checks'].pop()
            if mutation == 'duplicate-check': p['checks'].append(copy.deepcopy(p['checks'][0]))
            if mutation == 'wrong-bound': p['paths'][0]['bound'] = 3
            if mutation == 'extra-param': p['forged'] = True
            with self.subTest(mutation=mutation), self.assertRaises(PathPlanError): self.admit(x)

    def test_count_capacity_is_independent_and_complete(self):
        name = 'path_counts_use_complete_filtered_bag_before_having_order_limit'
        for mutation in ['missing', 'one-kind', 'duplicate', 'wrong-occurrence', 'wrong-terminal', 'wrong-representation']:
            x = self.fixture(name)
            o = self.obligation(x['response'], 'ashlar.path.countCapacity')
            if mutation == 'missing': x['response']['obligations'].remove(o)
            if mutation == 'one-kind': o['parameters']['checks'].pop()
            if mutation == 'duplicate': o['parameters']['checks'][1] = copy.deepcopy(o['parameters']['checks'][0])
            if mutation == 'wrong-occurrence': o['parameters']['checks'][0]['pathOccurrence'] = 'wrong'
            if mutation == 'wrong-terminal': next(c for c in x['response']['columns'] if 'pathTarget' in c['representation'])['representation']['pathTarget']['record']['element'] = 'wrong'
            if mutation == 'wrong-representation': o['parameters']['nativeRepresentation'] = 'DOUBLE'
            with self.subTest(mutation=mutation), self.assertRaises(PathPlanError): self.admit(x)

    def test_left_and_positioned_correspondence(self):
        for mutation in ['missing', 'wrong-map', 'wrong-carrier']:
            x = self.fixture('repeated_logical_labels_retain_the_exact_positioned_host_map')
            o = self.obligation(x['response'], 'weft.output.positioned')
            if mutation == 'missing': x['response']['obligations'].remove(o)
            if mutation == 'wrong-map': o['parameters']['columns'][0]['sourceIdentities'] = []
            if mutation == 'wrong-carrier': x['response']['columns'][1]['carrierName'] = x['response']['columns'][0]['carrierName']
            with self.subTest(mutation=mutation), self.assertRaises(PathPlanError): self.admit(x)
        for mutation in ['missing', 'wrong-uuid', 'wrong-scan', 'wrong-presence']:
            x = self.fixture('left_root_distinguishes_absence_and_retains_native_match_inventory')
            o = self.obligation(x['response'], 'outerJoin.matchIntegrity')
            if mutation == 'missing': x['response']['obligations'].remove(o)
            if mutation == 'wrong-uuid': o['parameters']['scans'][0]['table']['uuid'] = 'wrong'
            if mutation == 'wrong-scan': o['parameters']['scans'][0]['scan'] = 'wrong'
            if mutation == 'wrong-presence': next(c for c in x['response']['columns'] if c['representation']['kind'] == 'relatedPaths')['representation'].pop('outerJoin')
            with self.subTest(mutation=mutation), self.assertRaises(PathPlanError): self.admit(x)

    def test_schema_port_is_pinned_and_refusal_not_claim(self):
        wrong = dict(SCHEMAS); wrong[next(iter(wrong))] += b' '
        with self.assertRaises(PathPlanError): PathSchemaValidation(wrong, lambda *_: None)
        x = self.fixture('original_collection_retains_pins_keys_wide_order_and_closed_inventory')
        for callback in [lambda *_: True, lambda *_: (_ for _ in ()).throw(ValueError('secret payload'))]:
            config = PathAdmissionConfig(16000000, PathSchemaValidation(SCHEMAS, callback))
            with self.assertRaises(PathPlanError) as caught:
                admit_path_artifact(x['request'], x['response'], x['response'], config=config)
            self.assertNotIn('secret', str(caught.exception))
        def mutate_candidate(bundle, name, candidate): candidate.clear()
        config = PathAdmissionConfig(16000000, PathSchemaValidation(SCHEMAS, mutate_candidate))
        self.assertTrue(admit_path_artifact(x['request'], x['response'], x['response'], config=config).columns)

    def test_early_resource_bound_and_duplicate_json(self):
        x = self.fixture('original_collection_retains_pins_keys_wide_order_and_closed_inventory')
        x['request']['sql'] = 'x' * 10001
        config = PathAdmissionConfig(10000, self.config.schema_validation)
        with patch.object(module.json.JSONEncoder, 'iterencode', side_effect=AssertionError('must preflight first')):
            with self.assertRaises(PathPlanError): admit_path_artifact(x['request'], x['response'], x['response'], config=config)
        self.assertFalse(self.calls)
        for raw in ['{"profile":"a","profile":"b"}', '{"number":' + '9' * 1000 + '}', '{"number":1.5}']:
            x = self.fixture('original_collection_retains_pins_keys_wide_order_and_closed_inventory')
            x['request']['target']['bindingJson'] = raw
            with self.assertRaises(PathPlanError): self.admit(x)

    def test_owning_arithmetic_guard_is_not_optional(self):
        x = self.fixture('scalar_parameters_and_arithmetic_keep_original_tokens_and_separate_guards')
        x['response']['obligations'].remove(self.obligation(x['response'], 'ashlar.arithmetic.exact'))
        with self.assertRaises(PathPlanError): self.admit(x)

    def test_exact_target_and_bound_relationship_population(self):
        name = 'original_collection_retains_pins_keys_wide_order_and_closed_inventory'
        for key, value in [('id', 'other-profile'), ('engineVersion', '3.5.3'), ('publicationRevision', 'other'), ('storageLayoutRevision', 'other')]:
            x = self.fixture(name)
            x['response']['targetContext'][key] = value
            with self.subTest(key=key), self.assertRaises(PathPlanError): self.admit(x)
        x = self.fixture(name)
        binding = json.loads(x['request']['target']['bindingJson'])
        binding['relationships'][0]['kind'] = 'object'
        text = json.dumps(binding, sort_keys=True, separators=(',', ':'))
        digest = hashlib.sha256(text.encode()).hexdigest()
        x['request']['target']['bindingJson'] = text
        x['request']['target']['bindingSha256'] = digest
        x['response']['bindingSha256'] = digest
        with self.assertRaises(PathPlanError): self.admit(x)

    def test_checks_and_envelopes_remain_closed(self):
        name = 'original_collection_retains_pins_keys_wide_order_and_closed_inventory'
        for mutation in ['missing-owning', 'wrong-owner', 'unknown-member', 'unselected-kind', 'partial-publication']:
            x = self.fixture(name)
            o = self.obligation(x['response'], 'ashlar.path.occurrenceIntegrity')
            if mutation == 'missing-owning': x['response']['obligations'].remove(self.obligation(x['response'], 'ashlar.candidate.relationshipIntegrity'))
            if mutation == 'wrong-owner': o['owner'] = 'backend'
            if mutation == 'unknown-member': o['parameters']['checks'][0]['forged'] = True
            if mutation == 'unselected-kind': o['parameters']['checks'][0]['kind'] = 'pathRows'
            if mutation == 'partial-publication': o['parameters']['noPartialPublication'] = False
            with self.subTest(mutation=mutation), self.assertRaises(PathPlanError): self.admit(x)

    def test_left_native_identity_role_is_exact_even_empty(self):
        name = 'left_root_distinguishes_absence_and_retains_native_match_inventory'
        for key, value in [('identityColumn', 'not_id'), ('nativeType', 'STRING')]:
            x = self.fixture(name)
            scan = self.obligation(x['response'], 'outerJoin.matchIntegrity')['parameters']['scans'][0]
            scan[key] = value
            with self.subTest(key=key), self.assertRaises(PathPlanError): self.admit(x)
        x = self.fixture(name)
        scan = self.obligation(x['response'], 'outerJoin.matchIntegrity')['parameters']['scans'][0]
        binding = json.loads(x['request']['target']['bindingJson'])
        next(r for r in binding['records'] if r['logical'] == scan['record'])['kind'] = 'edge'
        text = json.dumps(binding, sort_keys=True, separators=(',', ':'))
        digest = hashlib.sha256(text.encode()).hexdigest()
        x['request']['target']['bindingJson'] = text
        x['request']['target']['bindingSha256'] = digest
        x['response']['bindingSha256'] = digest
        with self.assertRaises(PathPlanError): self.admit(x)

    def test_del_escape_budget_refuses_before_encoder(self):
        with patch.object(module.json.JSONEncoder, 'iterencode', side_effect=AssertionError('must preflight DEL expansion')):
            with self.assertRaises(PathPlanError): module._snapshot('\x7f' * 1000, 1100)
